    private static readonly Dictionary<string, Geometry> Cache = new();

    private static Geometry Get(string key, string pathData)
    {
        if (!Cache.TryGetValue(key, out var geom))
        {
            geom = Geometry.Parse(pathData);
            geom.Freeze();
            Cache[key] = geom;
        }
        return geom;
    }

